export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed, g = inputs.gravity;
  const T = u / g, H = u * u / (2 * g);
  const t = Math.max(0, Math.min(time, 2 * T));
  const yt = u * t - g * t * t / 2;
  const vt = u - g * t;
  const rel = t >= T;
  const tau = t - T;
  const yd = rel ? H - g * tau * tau / 2 : H;
  const vd = rel ? -g * tau : 0;
  const ad = rel ? -g : 0;
  const sy = sdk.linear([0, 2.2], [350, 90]);
  const tossState = t < 0.001 ? 'At launch' : (Math.abs(t - T) < 0.005 ? 'At the top' : (t < T ? 'Rising' : (t >= 2 * T - 0.001 ? 'At launch height' : 'Falling')));
  const dropState = !rel ? 'Held in place' : (t >= 2 * T - 0.001 ? 'At launch height' : (tau < 0.15 ? 'Just released' : 'Falling together'));
  const o = [];
  o.push(...sdk.panel({ id: 'lane.toss', x: 20, y: 40, w: 295, h: 360, title: 'Toss', state: tossState, role: 'input' }));
  o.push(...sdk.panel({ id: 'lane.drop', x: 325, y: 40, w: 295, h: 360, title: 'Drop', state: dropState, role: 'output' }));
  const bx1 = 140, bx2 = 445;
  o.push(...sdk.groundMark('mark.toss', bx1, 350, 120, 'launch'));
  o.push(...sdk.groundMark('mark.drop', bx2, 350, 120, 'launch'));
  o.push(...sdk.gate('gate', bx2, sy(H) - 22, { open: rel, w: 40 }));
  if (rel) {
    o.push(sdk.circle('ghost.drop', bx2, sy(H), 24, { opacity: 0.25 }));
    o.push(sdk.circle('ghost.toss', bx1, sy(H), 24, { opacity: 0.25 }));
  }
  o.push(sdk.circle('ball.toss', bx1, sy(yt), 28));
  o.push(sdk.circle('ball.drop', bx2, sy(yd), 28));
  const vs = 8, as = 3;
  o.push(...sdk.vector('vec.v.toss', { x: bx1 - 30, y: sy(yt) }, { value: vt, direction: 'up' }, { scale: vs, label: 'v', role: 'observed' }));
  o.push(...sdk.vector('vec.a.toss', { x: bx1 + 30, y: sy(yt) }, { value: -g, direction: 'up' }, { scale: as, label: 'a', role: 'warning' }));
  o.push(...sdk.vector('vec.v.drop', { x: bx2 - 30, y: sy(yd) }, { value: vd, direction: 'up' }, { scale: vs, label: 'v', role: 'observed' }));
  o.push(...sdk.vector('vec.a.drop', { x: bx2 + 30, y: sy(yd) }, { value: ad, direction: 'up' }, { scale: as, label: 'a', role: 'warning' }));
  o.push(...sdk.callout(bx1 + 55, sy(yt) - 30, ['v ' + sdk.format(vt, 2) + ' m/s', 'a ' + sdk.format(-g, 1) + ' m/s^2'], { id: 'callout.toss' }));
  o.push(...sdk.callout(bx2 + 55, sy(yd) - 30, ['v ' + sdk.format(vd, 2) + ' m/s', 'a ' + sdk.format(ad, 1) + ' m/s^2'], { id: 'callout.drop' }));
  return {
    frame: { width: 640, height: 420, objects: o, readouts: [
      { id: 'tossedVelocity', value: vt }, { id: 'tossedAcceleration', value: -g },
      { id: 'dropVelocity', value: vd }, { id: 'dropAcceleration', value: ad }] },
    quantities: { launchSpeed: u, gravity: g, apexTime: T, apexHeight: H, tossedVelocity: vt, tossedAcceleration: -g, tossedHeight: yt, dropVelocity: vd, dropAcceleration: ad, dropHeight: yd }
  };
}
